package dev.cardadvisor.finance;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.context.annotation.Import;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"codef.config-file=","codef.storage-key-file=","openai.config-file=","account.mail-config-file="})
@Import(FinancialConnectionsPostgresTest.LocalProviderConfiguration.class)
@EnabledIfEnvironmentVariable(named="RUN_DEVICE_FREE_ANDROID_TEST",matches="true")
class AndroidCardOwnershipPostgresTest{
 @LocalServerPort int port;@Autowired JdbcTemplate db;@Autowired FinancialConnectionsPostgresTest.Stub provider;
 String adb(String...args)throws Exception{var c=new ArrayList<String>(List.of(System.getenv("LOCALAPPDATA")+"/Android/Sdk/platform-tools/adb.exe","-s","emulator-5554"));c.addAll(List.of(args));var p=new ProcessBuilder(c).redirectErrorStream(true).start();var read=CompletableFuture.supplyAsync(()->{try{return new String(p.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){return "";}});if(!p.waitFor(120,TimeUnit.SECONDS)){p.destroyForcibly();fail("Synthetic Android timeout");}assertEquals(0,p.exitValue());return read.get(3,TimeUnit.SECONDS);}
 @Test void ownershipUiCreatesAndUpdatesWithoutStoringAuthentication()throws Exception{
  String run=UUID.randomUUID().toString();provider.calls.clear();provider.behaviors.clear();var report=new LinkedHashMap<String,Object>();report.put("passed",false);report.put("physicalDevice",false);report.put("actualProviderCalls",0);
  try{adb("reverse","tcp:18080","tcp:"+port);String output=adb("shell","am","instrument","-w","-r","-e","class","dev.cardadvisor.android.CardOwnershipFlowTest","-e","runId",run,"dev.cardadvisor.android.test/androidx.test.runner.AndroidJUnitRunner");report.put("failureLocations",java.util.regex.Pattern.compile("CardOwnershipFlowTest\\.kt:[0-9]+").matcher(output).results().map(java.util.regex.MatchResult::group).distinct().toList());assertTrue(output.contains("OK (1 test)"),"Synthetic ownership UI failed; raw output withheld");UUID user=db.queryForObject("SELECT id FROM app_users WHERE email=?",UUID.class,"ownership-ui-"+run+"@example.test");assertEquals(1,db.queryForObject("SELECT count(*) FROM financial_connections WHERE user_id=? AND state='ACTIVE'",Integer.class,user));assertEquals(2,db.queryForObject("SELECT count(*) FROM financial_connection_operations WHERE user_id=? AND status='SUCCEEDED'",Integer.class,user));assertEquals(2,provider.calls.size());for(String value:db.queryForList("SELECT row_to_json(c)::text FROM financial_connections c WHERE user_id=? UNION ALL SELECT row_to_json(o)::text FROM financial_connection_operations o WHERE user_id=?",String.class,user,user)){assertFalse(value.contains("9".repeat(16)));assertFalse(value.contains("cardPassword"));assertFalse(value.contains("SYNTHETIC_PASSWORD_ONLY"));}report.put("passed",true);
  }finally{db.update("DELETE FROM app_users WHERE email=?","ownership-ui-"+run+"@example.test");adb("reverse","--remove","tcp:18080");Files.writeString(Path.of("../.run/ownership-android.json"),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(report));}
 }
}
